import Foundation
import CoreImage
import CoreGraphics

/// Original Python source 2D DIR physical inhibitor samples, both
/// CPU Float64 FIR/YVV and the REAL CoreImage spatial production stage.
/// Source vectors generated by direct upstream model/couplers.py calls.
/// These are fixed-image, fixed-sigma tests, not full-image certification.
enum SourceSpatialDIR2DParity {
    enum Failure:LocalizedError {
        case invalid(String)
        var errorDescription:String? {
            if case .invalid(let s)=self { return s }
            return nil
        }
    }
    struct Evidence {
        let cases:Int
        let channels:Int
        let numericOutside:Int
        let productionOutside:Int
        let numericMAE:Double
        let numericMax:Double
        let productionMAE:Double
        let productionMax:Double
        let text:String
    }
    private struct Metrics {
        var sum=0.0
        var max=0.0
        var outside=0
        var worst=""
        mutating func test(source:Double,actual:Double,label:String) throws {
            guard source.isFinite && actual.isFinite else {
                throw Failure.invalid("原版二维 DIR 产生非有限数：" + label)
            }
            let d=abs(source-actual)
            sum+=d
            if d>max { max=d; worst="\(label) Python=\(source) Swift=\(actual)" }
            if d>0.002 { outside+=1 }
        }
        func describe(_ name:String,channels:Int)->String {
            return "\(name): MAE=\(sum/Double(channels)), max=\(max), " +
                   "超限=\(outside)/\(channels), 最差项：\(worst)"
        }
    }
    /// IEEE-754 binary16 round-to-nearest ties-to-even reference.
    /// Intel macOS native Swift test compilers do not expose Float16(_:)
    /// consistently. Work directly on the Float32 bit pattern instead;
    /// this is a diagnostic only and does not modify production pixels.
    private static func float16Reference(_ value:Double) -> Double {
        let bits=Float(value).bitPattern
        let sign=(bits >> 16) & 0x8000
        let exponent=Int((bits >> 23) & 0xff)
        let fraction=bits & 0x7fffff
        var half=sign
        if exponent == 255 {
            half |= 0x7c00 | (fraction == 0 ? 0 : 0x0200)
        } else if exponent >= 143 {
            half |= 0x7c00
        } else if exponent >= 113 {
            var e=exponent-112
            var mantissa=fraction >> 13
            let remainder=fraction & 0x1fff
            if remainder > 0x1000 ||
                (remainder == 0x1000 && (mantissa & 1) != 0) {
                mantissa += 1
            }
            if mantissa == 1024 { e += 1; mantissa=0 }
            half |= (UInt32(e) << 10) | mantissa
        } else if exponent >= 102 {
            let mantissa:UInt32=0x800000 | fraction
            let shift=126-exponent
            var rounded=mantissa >> shift
            let rem=mantissa & ((UInt32(1) << shift)-1)
            let tie=UInt32(1) << (shift-1)
            if rem > tie || (rem == tie && (rounded & 1) != 0) {
                rounded += 1
            }
            half |= rounded
        }
        let halfExponent=(half >> 10) & 0x1f
        let halfFraction=half & 0x3ff
        let sign32=(half & 0x8000) << 16
        if halfExponent == 0 {
            if halfFraction == 0 {
                return Double(Float(bitPattern:sign32))
            }
            let magnitude=Float(halfFraction) / 16_777_216.0
            return Double(sign32 == 0 ? magnitude : -magnitude)
        }
        let resultBits:UInt32
        if halfExponent == 31 {
            resultBits=sign32 | 0x7f800000 |
                (halfFraction == 0 ? 0 : halfFraction << 13)
        } else {
            resultBits=sign32 | ((halfExponent+112) << 23) |
                (halfFraction << 13)
        }
        return Double(Float(bitPattern:resultBits))
    }

    private static func cube(_ n:Int) -> Data {
        var floats=[Float]()
        floats.reserveCapacity(n*n*n*4)
        let step=Float(1.0/Double(n-1))
        for b in 0..<n {
            for g in 0..<n {
                for r in 0..<n {
                    floats.append(contentsOf:[
                        Float(r)*step,Float(g)*step,Float(b)*step,1.0
                    ])
                }
            }
        }
        return floats.withUnsafeBufferPointer {
            Data(bytes:$0.baseAddress!,count:floats.count*4)
        }
    }
    private static func image(_ rgb:[Double],width:Int,height:Int) -> CIImage {
        var rgba=[Float](repeating:1,count:width*height*4)
        for i in 0..<(width*height) {
            for c in 0..<3 { rgba[i*4+c]=Float(rgb[i*3+c]) }
        }
        let data=rgba.withUnsafeBytes { Data($0) }
        return CIImage(
            bitmapData:data,bytesPerRow:width*4*MemoryLayout<Float>.size,
            size:CGSize(width:width,height:height),
            format:.RGBAf,colorSpace:nil
        )
    }
    private static func read(
        _ source:CIImage,width:Int,height:Int,
        softwareRenderer:Bool=false
    ) -> [Double] {
        // Measure the iOS Core Image working-buffer boundary on device.
        // RGBAf destination does NOT guarantee Float32 intermediates:
        // the default iOS CI working format is RGBAh (Float16).
        let context=CIContext(options:[
            .workingColorSpace:NSNull(),.outputColorSpace:NSNull(),
            .useSoftwareRenderer:softwareRenderer
        ])
        var data=[Float](repeating:0,count:width*height*4)
        data.withUnsafeMutableBytes { ptr in
            context.render(source,toBitmap:ptr.baseAddress!,
                           rowBytes:width*4*MemoryLayout<Float>.size,
                           bounds:CGRect(x:0,y:0,width:width,height:height),
                           format:.RGBAf,colorSpace:nil)
        }
        var rgb=[Double](repeating:0,count:width*height*3)
        for i in 0..<(width*height) {
            for c in 0..<3 { rgb[i*3+c]=Double(data[i*4+c]) }
        }
        return rgb
    }

    static func evaluate() throws -> Evidence {
        let cases=GeneratedSourceSpatialDIR2D.samples
        guard cases.count==3 else {
            throw Failure.invalid("二维源 DIR Python 参考样本不是三组")
        }
        let sourceIdentity=cube(9),correctedIdentity=cube(17)
        var numeric=Metrics(),production=Metrics()
        var sourceInputBridge=Metrics(),floatBitmapBridge=Metrics()
        // v1.8.17 isolates source Float32 rounding, Float16 rounding,
        // default GPU Core Image, and software Core Image independently.
        // These are observational metrics, not evidence of full-image
        // Float64 equivalence, and MUST NOT relax the parity threshold.
        var directFloat32=Metrics(),directFloat16=Metrics()
        var softwareInputBridge=Metrics()
        var halfSignatureCount=0,affectedInputCount=0
        let stageNames=[
            "raw","initial","inhibitors","diffused",
            "log","densityPreGrain","printed"
        ]
        var stageStatistics=[String:Metrics]()
        for name in stageNames {stageStatistics[name]=Metrics()}
        var total=0
        var report=[String]()
        for (n,c) in cases.enumerated() {
            let count=c.width*c.height*3
            guard c.input.count==count &&
                  c.sourceInhibitors.count==count &&
                  c.sourceDiffused.count==count &&
                  c.sourceCorrected.count==count &&
                  c.sourceNormalizedDisplay.count==count &&
                  c.matrix.count==9,c.densityMaximum.count==3 else {
                throw Failure.invalid("二维源 DIR 图像尺寸／三通道参考数据无效")
            }
            let cpu=try SourceSpatialDIRConvolution.diffuse(
                c.sourceInhibitors,width:c.width,height:c.height,
                coreSigma:20*c.radiusScale/c.pixelUM,
                tailSigma:200*c.radiusScale/c.pixelUM,
                tailWeight:c.tailWeight
            )
            for i in 0..<count {
                try numeric.test(
                    source:c.sourceDiffused[i],actual:cpu[i],
                    label:"\(c.film) #\(n) pixel:\(i/3) ch:\(i%3)"
                )
            }
            // Diagnose the EXACT image ingestion and Float32 CIImage
            // bridge separately; never obscure a true production error.
            let prepared=image(c.input,width:c.width,height:c.height)
            let roundTrip=read(prepared,width:c.width,height:c.height)
            let softwareRoundTrip=read(
                prepared,width:c.width,height:c.height,softwareRenderer:true
            )
            for i in 0..<count {
                let label="\(c.film) input #\(n) pixel:\(i/3) ch:\(i%3)"
                let f32=Double(Float(c.input[i]))
                let f16=float16Reference(c.input[i])
                try directFloat32.test(
                    source:c.input[i],actual:f32,label:label
                )
                try directFloat16.test(
                    source:c.input[i],actual:f16,label:label
                )
                try sourceInputBridge.test(
                    source:c.input[i],actual:roundTrip[i],label:label
                )
                try softwareInputBridge.test(
                    source:c.input[i],actual:softwareRoundTrip[i],label:label
                )
                if abs(roundTrip[i]-f16) < 1.0e-7 {
                    halfSignatureCount+=1
                }
                if abs(roundTrip[i]-f32) > 1.0e-7 {
                    affectedInputCount+=1
                }
            }
            let bridgeOutput=try SourceSpatialDIRConvolution.diffuseCI(
                image(c.sourceInhibitors,width:c.width,height:c.height),
                coreSigma:20*c.radiusScale/c.pixelUM,
                tailSigma:200*c.radiusScale/c.pixelUM,
                tailWeight:c.tailWeight
            )
            let bridgeValues=read(bridgeOutput,width:c.width,height:c.height)
            for i in 0..<count {
                try floatBitmapBridge.test(
                    source:c.sourceDiffused[i],actual:bridgeValues[i],
                    label:"\(c.film) CI bridge #\(n) pixel:\(i/3) ch:\(i%3)"
                )
            }
            let stage=SpatialDIRStage(
                rawLogCube:sourceIdentity,
                initialDensityCube:sourceIdentity,
                correctedDensityCube:correctedIdentity,
                printCube:sourceIdentity,
                sourceCubeSize:9,correctedCubeSize:17,
                densityRanges:[1,1,1],
                densityMaximum:c.densityMaximum,
                logExposureSpans:[2,2,2],
                donorReceiverMatrix:c.matrix,
                positive:c.positive
            )
            var opts=SpatialDIRSettings(enabled:true)
            opts.diffusionRadiusScale=c.radiusScale
            opts.tailWeight=c.tailWeight
            opts.referencePixelSizeUM=c.pixelUM
            opts.sourceConvolutionEnabled=true
            var stageImages=[String:[Double]]()
            guard opts.valid,stage.valid,
                  let actual=try SpatialDIR.apply(
                    to:prepared,
                    stage:stage,settings:opts,grain:nil,
                    stageObserver:{ name,image in
                        stageImages[name]=read(
                            image,width:c.width,height:c.height
                        )
                    }
                  ) else {
                throw Failure.invalid("原版二维 DIR 生产 CIImage 管线返回空输出")
            }
            let references:[String:[Double]]=[
                "raw":c.input,
                "initial":c.input,
                "inhibitors":c.sourceInhibitors,
                "diffused":c.sourceDiffused,
                "log":c.sourceNormalizedDisplay,
                "densityPreGrain":c.sourceNormalizedDisplay,
                "printed":c.sourceNormalizedDisplay
            ]
            for key in stageNames {
                guard let observed=stageImages[key],
                      let reference=references[key],
                      observed.count==count,reference.count==count else {
                    throw Failure.invalid("原版 DIR 中间阶段缺失：" + key)
                }
                for i in 0..<count {
                    try stageStatistics[key]!.test(
                        source:reference[i],actual:observed[i],
                        label:"\(c.film) stage \(key) #\(n) px:\(i/3) ch:\(i%3)"
                    )
                }
            }
            let rendered=read(actual,width:c.width,height:c.height)
            for i in 0..<count {
                try production.test(
                    source:c.sourceNormalizedDisplay[i],actual:rendered[i],
                    label:"\(c.film) #\(n) pixel:\(i/3) ch:\(i%3)"
                )
            }
            report.append("\(c.film) \(c.positive ? "正片" : "负片") " +
                          "\(c.width)×\(c.height), μm/px=\(c.pixelUM), " +
                          "Gaussian sigma=\(20*c.radiusScale/c.pixelUM), " +
                          "尾巴权重=\(c.tailWeight)")
            total+=count
        }
        let text="""
            原版 Python 二维空间 DIR（非仅矩阵点样本）：
            \(cases.count) 组不同正负片、曝光空间变化、FIR/YVV IIR
            + 3-Gaussian exponential tail，共 \(total) 个通道像素。
            \(numeric.describe("源 Float64 FIR/YVV 扩散",channels:total))
            【v1.8.17 原版图像精度边界诊断｜不计入整图认证】
            \(directFloat32.describe("不经过 CI 的直接 Float32 量化",channels:total))
            \(directFloat16.describe("不经过 CI 的 IEEE binary16 量化（ties-to-even）",channels:total))
            \(sourceInputBridge.describe("默认 CIImage RGBAf 输入校验（通常为 GPU）",channels:total))
            \(softwareInputBridge.describe("请求软件渲染 CIImage RGBAf 输入校验",channels:total))
            默认 CI 与 Float16 数值吻合：\(halfSignatureCount)/\(total)；
            默认 CI 偏离直接 Float32 超过 1e-7：\(affectedInputCount)/\(total)。
            两个 CIContext 均只用于测量，不据此切换生产算法。\n            提示：softwareRenderer 依赖平台支持，iOS 可能忽略此请求；\n            本结果不得直接认定使用了 CPU 渲染器。
            \(floatBitmapBridge.describe("Float32 CIImage→FIR/YVV→CIImage 桥接",channels:total))
            \(stageNames.map {stageStatistics[$0]!.describe("实际生产阶段 "+$0,channels:total)}
                        .joined(separator:"\\n"))
            \(production.describe("真实 CIImage 生产 DIR→光学 LUT",channels:total))
            数值门限 0.002；不包含空间 DIR 后整幅照片的原版相纸随机颗粒，
            不包含原版 Numba 线程 RNG 和相机传感器 RAW。真实照片仍需实机验证。
            配置：\(report.joined(separator:"；"))
            """
        return Evidence(
            cases:cases.count,channels:total,
            numericOutside:numeric.outside,
            productionOutside:production.outside,
            numericMAE:numeric.sum/Double(total),numericMax:numeric.max,
            productionMAE:production.sum/Double(total),
            productionMax:production.max,text:text
        )
    }
}
